from typing import Dict

import numpy as np


def stepinfo_3d(
    pos_actual: np.ndarray,
    pos_target: np.ndarray,
    t: np.ndarray,
    settling_threshold: float = 0.02,
) -> Dict[str, float]:
    """Compute 3D step metrics using Euclidean distance to target."""

    if pos_actual.shape[0] != 3:
        raise ValueError("pos_actual must have shape (3, n)")

    dist = np.linalg.norm(pos_actual.T - pos_target.reshape(1, 3), axis=1)
    d0 = float(dist[0])

    if d0 < 1e-6:
        return {
            "RiseTime": 0.0,
            "SettlingTime": 0.0,
            "Overshoot_pct": 0.0,
            "SteadyStateError": float(dist[-1]),
        }

    rise_time = float(t[-1])
    for k in range(dist.size):
        if dist[k] <= 0.1 * d0:
            rise_time = float(t[k])
            break

    band = settling_threshold * d0
    settling_time = 0.0
    for k in range(dist.size - 1, -1, -1):
        if dist[k] > band:
            settling_time = float(t[k])
            break

    # Overshoot: max distance after first entering the settling band.
    entry_idx = None
    for k in range(dist.size):
        if dist[k] <= band:
            entry_idx = k
            break

    if entry_idx is None:
        overshoot_pct = 0.0
    else:
        max_post = float(np.max(dist[entry_idx:]))
        overshoot_pct = 100.0 * max_post / d0

    return {
        "RiseTime": float(rise_time),
        "SettlingTime": float(settling_time),
        "Overshoot_pct": float(overshoot_pct),
        "SteadyStateError": float(dist[-1]),
    }
"}

