cmds = sorted(Path('/root/commands').glob('*.txt'))
missing=[]
for c in cmds:
    d=Path('/root/results')/c.stem
    req=['metrics_3d.json','tuning_results.json','planned_trajectory.npy','actual_trajectory.npy']
    for r in req:
        if not (d/r).exists():
            missing.append((c.stem,r))
    for img in ['desired_vs_actual.png','errors.png','cumulative_errors.png']:
        if not (d/'plots'/img).exists():
            missing.append((c.stem,'plots/'+img))
print('missing', len(missing))
if missing:
    print(missing[:20])
else:
    # quick constraint spot-check on a few
    for stem in ['002','018','021','030']:
        traj=np.load(f'/root/results/{stem}/planned_trajectory.npy')
        act=np.load(f'/root/results/{stem}/actual_trajectory.npy')
        pe=np.linalg.norm(act[0:3,:]-traj[0:3,:],axis=0)
        print(stem,'max_pos_err',pe.max())
PY"}

